-- Integration regression: all fixtures and mutations are rolled back, including sessions.
begin;
do $$
declare actor uuid; uid uuid; tid uuid; uid2 uuid; tid2 uuid; yr uuid; sem integer; unit uuid; cl uuid; cl2 uuid; sub uuid; sub2 uuid; op uuid; aid uuid; sid uuid; result jsonb; items jsonb; n bigint; before_count bigint; rejected boolean; test_token text;
begin
 select a.id into actor from public.user_accounts a join public.user_roles r on a.teacher_id=r.teacher_id where r.role_code='admin' and r.is_active and a.status='AKTIF' limit 1;
 assert actor is not null,'admin fixture missing';
 select y.id,y.school_unit_id,s.semester_no into yr,unit,sem from public.academic_years y join public.semesters s on s.academic_year_id=y.id where y.is_active and s.is_active;
 insert into public.role_catalog(role_code,display_name,is_active) values('cq_regression_role','Regression only',true);
 result:=public.cq_admin_save_user_v1(actor,null,null,'CQ Regression','cq.regression.'||substr(gen_random_uuid()::text,1,8),null,'AKTIF','not-a-login-hash',array['guru','walas','cq_regression_role']);
 uid:=(result->>'user_id')::uuid;
 select teacher_id into tid from public.user_accounts where id=uid;
 assert (select count(*) from public.user_roles where teacher_id=tid and is_active)=3,'all requested roles must persist';
 insert into public.user_sessions(user_account_id,token_hash,expires_at) values(uid,encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'),now()+interval '1 hour') returning id into sid;
 perform public.cq_admin_save_user_v1(actor,uid,null,'CQ Regression',(select username from public.user_accounts where id=uid),null,'AKTIF',null,array['guru','walas','cq_regression_role']);
 assert (select revoked_at is null from public.user_sessions where id=sid),'unchanged roles must keep session';
 rejected:=false;
 begin
   perform public.cq_admin_save_user_v1(actor,uid,null,'WRONG',(select username from public.user_accounts where id=uid),null,'AKTIF',null,array['missing_role']);
 exception when others then rejected:=SQLERRM='invalid_or_inactive_role'; end;
 assert rejected and (select full_name='CQ Regression' from public.teachers where id=tid),'invalid role must not partly save profile';
 update public.role_catalog set is_active=false where role_code='cq_regression_role';
 assert not exists(select 1 from public.user_roles where teacher_id=tid and role_code='cq_regression_role' and is_active),'catalog disable revokes grant';
 assert (select revoked_at is not null from public.user_sessions where id=sid),'catalog disable revokes session';
 update public.role_catalog set is_active=true where role_code='cq_regression_role';
 assert not exists(select 1 from public.user_roles where teacher_id=tid and role_code='cq_regression_role' and is_active),'re-enable must not resurrect grants';
 rejected:=false;
 begin update public.role_catalog set is_active=false where role_code='admin'; exception when others then rejected:=SQLERRM='admin_role_required'; end;
 assert rejected,'admin catalog cannot be disabled';
 rejected:=false;
 begin perform public.cq_admin_save_user_v1(actor,actor,null,'Admin',(select username from public.user_accounts where id=actor),null,'AKTIF',null,array['guru']); exception when others then rejected:=SQLERRM in ('cannot_remove_own_admin','admin_account_required'); end;
 assert rejected,'cannot remove own admin';
 perform public.cq_admin_save_user_v1(actor,uid,null,'CQ Regression',(select username from public.user_accounts where id=uid),null,'AKTIF',null,array['admin','guru','walas','cq_regression_role']);
 test_token:=gen_random_uuid()::text;
 insert into public.user_sessions(user_account_id,token_hash,expires_at) values(uid,encode(extensions.digest(test_token,'sha256'),'hex'),now()+interval '1 hour');
 result:=public.role_catalog_manage(test_token,'upsert','admin','Admin',null,false);
 assert (result->>'error')='admin_role_required','upsert cannot disable admin';
 result:=public.role_catalog_manage(test_token,'toggle','cq_regression_role',null,null,false);
 assert (result->>'success')::boolean and (result->>'reauth_required')::boolean,'successful self revocation signals login instead of false failure';
 rejected:=false;
 begin update public.user_accounts set username='cq.renamed.root' where lower(username)='admin'; exception when others then rejected:=SQLERRM='reserved_admin_username'; end;
 assert rejected,'reserved admin username immutable';
 assert not has_function_privilege('anon','public.cq_admin_save_user_v1(uuid,uuid,uuid,text,text,text,text,text,text[])','execute'),'anonymous cannot mutate users';
 assert not has_function_privilege('authenticated','public.cq_admin_assignments_v1(uuid,uuid,integer,uuid,jsonb,uuid,text,uuid)','execute'),'authenticated cannot bypass Edge';
 select id into cl from public.classes c where academic_year_id=yr and is_active and (select count(*) from public.class_partner_assignments p where p.class_id=c.id and p.academic_year_id=yr and p.semester_no=sem and p.is_active)<3 order by id limit 1;
 select id into cl2 from public.classes where academic_year_id=yr and is_active and id<>cl order by id limit 1;
 select id into sub from public.subjects where school_unit_id=unit and is_active order by id limit 1;
 select id into sub2 from public.subjects where school_unit_id=unit and is_active and id<>sub order by id limit 1;
 items:=jsonb_build_array(jsonb_build_object('assignment_type','guru_mapel','class_id',cl,'subject_id',sub),jsonb_build_object('assignment_type','guru_mapel','class_id',cl2,'subject_id',sub2),jsonb_build_object('assignment_type','guru_partner','class_id',cl),jsonb_build_object('assignment_type','guru_tahfizh','class_id',cl),jsonb_build_object('assignment_type','wali_kelas','class_id',cl));
 perform public.cq_admin_assignments_v1(actor,yr,sem,tid,items);
 assert (select count(*) from public.teacher_subject_assignments where teacher_id=tid and is_active)=2,'no cross-product';
 assert (select count(*) from public.admin_teacher_assignments where teacher_id=tid and is_active)=5,'four job types independent';
 perform public.cq_admin_assignments_v1(actor,yr,sem,tid,items);
 assert (select count(*) from public.admin_teacher_assignments where teacher_id=tid and is_active)=5,'repeat save must not duplicate';
 select count(*) into before_count from public.admin_teacher_assignments;
 rejected:=false;
 begin perform public.cq_admin_assignments_v1(actor,yr,sem,tid,jsonb_build_array(jsonb_build_object('assignment_type','tugas_tambahan','title','Must rollback'),jsonb_build_object('assignment_type','guru_mapel','class_id',cl,'subject_id',gen_random_uuid())));
 exception when others then rejected:=SQLERRM='subject_invalid'; end;
 assert rejected and (select count(*) from public.admin_teacher_assignments)=before_count,'invalid later item rolls back entire batch';
 rejected:=false;
 begin perform public.cq_admin_assignments_v1(actor,yr,3-sem,tid,items); exception when others then rejected:=SQLERRM='period_changed_reload'; end;
 assert rejected,'inactive semester rejected';
 select jsonb_agg(jsonb_build_object('assignment_type','guru_mapel','class_id',id,'subject_id',sub)) into items from (select id from public.classes where academic_year_id=yr and is_active order by id limit 8)c;
 perform public.cq_admin_assignments_v1(actor,yr,sem,tid,items);
 assert (select count(*) from public.teacher_subject_assignments where teacher_id=tid and subject_id=sub and is_active)>=8,'one subject across eight classes';
 select id into aid from public.admin_teacher_assignments where teacher_id=tid and assignment_type='guru_partner' and is_active;
 perform public.cq_admin_assignments_v1(actor,yr,sem,null,'[]',aid);
 assert not exists(select 1 from public.class_partner_assignments where teacher_id=tid and is_active),'deactivate operational partner';
 assert exists(select 1 from public.tahfizh_teacher_assignments where teacher_id=tid and is_active),'ending Partner must retain Tahfizh';
 assert exists(select 1 from public.admin_teacher_assignments where id=aid and not is_active),'keep partner history';
 perform public.cq_admin_assignments_v1(actor,yr,sem,tid,jsonb_build_array(jsonb_build_object('assignment_type','guru_partner','class_id',cl)));
 assert (select count(*) from public.class_partner_assignments where teacher_id=tid and is_active)=1,'partner reactivation reuses unique row';
 result:=public.cq_admin_save_user_v1(actor,null,null,'CQ Regression replacement','cq.replace.'||substr(gen_random_uuid()::text,1,8),null,'AKTIF','not-a-login-hash',array['guru']);
 uid2:=(result->>'user_id')::uuid;select teacher_id into tid2 from public.user_accounts where id=uid2;
 perform public.cq_admin_assignments_v1(actor,yr,sem,tid2,jsonb_build_array(jsonb_build_object('assignment_type','wali_kelas','class_id',cl)));
 assert exists(select 1 from public.admin_teacher_assignments where teacher_id=tid and class_id=cl and assignment_type='wali_kelas' and not is_active),'replacement retains former Walas history';
 select id into op from public.report_class_assignments where class_id=cl and academic_year_id=yr and semester_no=sem;
 rejected:=false;
 begin perform public.cq_admin_assignments_v1(actor,yr,sem,tid,'[]',null,'report_class_assignments',op); exception when others then rejected:=SQLERRM='assignment_not_found'; end;
 assert rejected,'stale Walas row cannot deactivate replacement';
 assert (select homeroom_teacher_id=tid2 from public.report_class_assignments where id=op),'replacement unchanged';
 -- Exercise importing a legacy row into history without deleting the source row.
 select id,teacher_id into op,tid2 from public.teacher_subject_assignments where academic_year_id=yr and semester_no=sem and is_active and teacher_id<>tid limit 1;
 perform public.cq_admin_assignments_v1(actor,yr,sem,tid2,'[]',null,'teacher_subject_assignments',op);
 assert exists(select 1 from public.admin_teacher_assignments where operational_id=op and teacher_id=tid2 and not is_active),'legacy assignment history';
 assert exists(select 1 from public.teacher_subject_assignments where id=op and not is_active),'legacy row retained';
 raise notice 'PASS: atomic users, multi-role, catalog revocation, unchanged-session preservation, self protection, grants, four jobs, mapel pairs/eight classes, rollback, period checks, replacement history, stale replacement guard, legacy deactivation';
end $$;
rollback;
select 'PASS: regression transaction rolled back' as result;
